import{_ as s,C as r,o as t,c as o,a0 as a,b as l,w as i,a as d,E as c,a1 as h}from"./chunks/framework.CzVS_xMp.js";const p="/ai-data-center-systems/assets/multithreaded-superscala-core.DnzPQlaW.png",u="/ai-data-center-systems/assets/nvidia-v100-gpu-sm-unit.ChuLyy34.png",m="data:image/svg+xml;base64,",g="/ai-data-center-systems/assets/processor-per-clock.B-x73R5D.png",y="/ai-data-center-systems/assets/ispc-iteration-assignment.COqA07VV.svg",P=JSON.parse('{"title":"Lecture 3: Multi-Core Architecture, Part II and ISPC","description":"","frontmatter":{},"headers":[],"relativePath":"gpu/cs149/lec03/index.md","filePath":"gpu/cs149/lec03/index.md","lastUpdated":1788490169000}'),b={name:"gpu/cs149/lec03/index.md"};function f(k,e,I,w,v,C){const n=r("Mermaid");return t(),o("div",null,[e[1]||(e[1]=a('<h1 id="lecture-3-multi-core-architecture-part-ii-and-ispc" tabindex="-1">Lecture 3: Multi-Core Architecture, Part II and ISPC <a class="header-anchor" href="#lecture-3-multi-core-architecture-part-ii-and-ispc" aria-label="Permalink to &quot;Lecture 3: Multi-Core Architecture, Part II and ISPC&quot;">​</a></h1><p>Source: <a href="https://www.youtube.com/watch?v=F4bVSyz_jxo" target="_blank" rel="noreferrer">Stanford CS149 2023 Lecture 3</a></p><p>Course materials:</p><ul><li><a href="https://gfxcourses.stanford.edu/cs149/fall23" target="_blank" rel="noreferrer">CS149 Fall 2023 course page</a></li><li><a href="https://gfxcourses.stanford.edu/cs149/fall23content/media/multicore/02_basicarch_xX3ssOi.pdf" target="_blank" rel="noreferrer">Lecture 2 slides PDF (review material)</a></li><li><a href="https://gfxcourses.stanford.edu/cs149/fall23content/media/multicore2-ispc/03_multicore2-ispc.pdf" target="_blank" rel="noreferrer">Lecture 3 slides PDF</a></li><li><a href="https://ispc.github.io/" target="_blank" rel="noreferrer">ISPC documentation</a></li><li><a href="https://pharr.org/matt/blog/2018/04/30/ispc-all" target="_blank" rel="noreferrer">The Story of ISPC</a></li></ul><blockquote><p>The video lecture covers a review of hardware multi-threading, latency and bandwidth, and ISPC&#39;s <code>foreach</code>. The data race, reduction, cross-instance operation, and ISPC task sections in these notes supplement the lecture slides that follow the video.</p></blockquote><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#goal">Goal</a></li><li><a href="#lecture-overview">Lecture Overview</a></li><li><a href="#visual-map">Visual Map</a></li><li><a href="#hardware-parallelism-review">Hardware Parallelism Review</a></li><li><a href="#hardware-multi-threading-and-latency-hiding">Hardware Multi-Threading and Latency Hiding</a></li><li><a href="#latency-and-bandwidth">Latency and Bandwidth</a></li><li><a href="#pipelining-and-the-slowest-stage">Pipelining and the Slowest Stage</a></li><li><a href="#memory-bandwidth-bound-execution">Memory Bandwidth-Bound Execution</a></li><li><a href="#arithmetic-intensity-and-data-reuse">Arithmetic Intensity and Data Reuse</a></li><li><a href="#abstraction-vs-implementation">Abstraction vs. Implementation</a></li><li><a href="#ispc-and-the-spmd-programming-model">ISPC and the SPMD Programming Model</a></li><li><a href="#ispc-gang-and-program-instances">ISPC Gang and Program Instances</a></li><li><a href="#uniform-and-varying-values">Uniform and Varying Values</a></li><li><a href="#interleaved-and-blocked-assignment">Interleaved and Blocked Assignment</a></li><li><a href="#the-foreach-abstraction">The <code>foreach</code> Abstraction</a></li><li><a href="#parallel-loop-correctness">Parallel Loop Correctness</a></li><li><a href="#reduction-and-cross-instance-operations">Reduction and Cross-Instance Operations</a></li><li><a href="#spmd-abstraction-and-simd-implementation">SPMD Abstraction and SIMD Implementation</a></li><li><a href="#ispc-tasks-and-multi-core-execution">ISPC Tasks and Multi-Core Execution</a></li><li><a href="#the-abstraction-ladder">The Abstraction Ladder</a></li><li><a href="#gpu-systems-lens">GPU Systems Lens</a></li><li><a href="#practical-tips-and-notes">Practical Tips and Notes</a></li><li><a href="#lecture-summary">Lecture Summary</a></li><li><a href="#key-terms">Key Terms</a></li><li><a href="#questions">Questions</a></li><li><a href="#answers">Answers</a></li></ul><hr><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>This lecture has two goals. First, understand that in a modern throughput processor, latency and bandwidth are different constraints. Second, distinguish the semantics of a parallel programming model from the implementation that maps it onto real hardware.</p><p>The core message is as follows.</p><blockquote><p>Many threads can hide memory latency, but they cannot increase memory bandwidth. And an ISPC programmer writes an SPMD program in which many program instances execute independently, while the compiler implements it as SIMD instructions on a single core. To understand performance precisely, look at the programming abstraction and the hardware implementation at the same time, but do not confuse the two.</p></blockquote><p>This lecture covers the following.</p><ul><li>The combination of multi-core, SIMD, superscalar, and hardware multi-threading</li><li>The relationship between the number of hardware threads and latency hiding</li><li>The difference between latency and bandwidth</li><li>Pipeline throughput and the slowest-stage bottleneck</li><li>Why vector multiplication can be memory-bound even when it is sufficiently parallel</li><li>The ratio of arithmetic work to memory traffic</li><li>Distinguishing the semantics of a programming model from its scheduling/implementation</li><li>ISPC&#39;s SPMD abstraction, gang, and program instance</li><li><code>programCount</code>, <code>programIndex</code>, <code>uniform</code>, and varying values</li><li>Interleaved/blocked iteration assignment and memory access cost</li><li>How <code>foreach</code> abstracts iteration assignment</li><li>Independence, data races, and reduction in parallel loops</li><li>SPMD-to-SIMD compilation and multi-core execution via ISPC tasks</li></ul><h2 id="lecture-overview" tabindex="-1">Lecture Overview <a class="header-anchor" href="#lecture-overview" aria-label="Permalink to &quot;Lecture Overview&quot;">​</a></h2><p>The first half of the lecture follows the end of the <a href="https://gfxcourses.stanford.edu/cs149/fall23content/media/multicore/02_basicarch_xX3ssOi.pdf" target="_blank" rel="noreferrer">Lecture 2 slides</a> and reviews the hardware model in more detail. Hardware multi-threading reduces idle cycles in execution units by running other threads while one thread waits for memory. However, if utilization has already reached 100%, adding more hardware threads does not increase throughput. On the contrary, it requires more chip area to store execution contexts, can increase the completion latency of individual threads, and can cause interference between threads over caches and execution resources.</p><p>The lecture then distinguishes latency from bandwidth. Latency is the time it takes for one request to complete, while bandwidth is the amount of data that can be completed per unit time. Through the analogies of a highway, a laundry pipeline, and connected pipes, it explains that the overall throughput of a pipeline is limited by the rate of its slowest stage.</p><p>Applying this principle to element-wise vector multiplication on a V100 yields an important conclusion. Millions of independent elements are enough to fill cores, SIMD lanes, and hardware threads, but each multiply must read two values and write one result. In FP32, that is 12 bytes of memory traffic per operation. To keep the V100&#39;s 5,120 FP32 ALUs running continuously at 1.6 GHz would require about 98 TB/s, but the HBM2 bandwidth given in the slides is 900 GB/s. Therefore this computation stays below 1% of peak compute efficiency due to a bandwidth shortage, not a parallelism shortage.</p><p>The second half uses ISPC to explain the gap between abstraction and implementation. When an ISPC function is called, a gang of many program instances logically executes the same program on different data. That is the SPMD semantics. In practice, the ISPC compiler transforms the gang&#39;s execution into SIMD instructions such as AVX. <code>foreach</code> raises the level of abstraction so the programmer only declares the independence of iterations and leaves the per-instance assignment to the compiler.</p><p>Based on the video&#39;s progress, the main segments are as follows.</p><table tabindex="0"><thead><tr><th>Time</th><th>Topic</th></tr></thead><tbody><tr><td><code>00:00–16:49</code></td><td>Hardware multi-threading, latency hiding, the number of threads needed</td></tr><tr><td><code>16:50–38:00</code></td><td>The combination of multi-core, SIMD, superscalar, and SMT; CPU/GPU comparison</td></tr><tr><td><code>38:01–46:20</code></td><td>The vector multiplication thought experiment; latency and bandwidth</td></tr><tr><td><code>46:21–53:27</code></td><td>Pipelining explained with a highway and laundry</td></tr><tr><td><code>53:28–01:03:12</code></td><td>Memory bandwidth-bound execution and the arithmetic-to-memory ratio</td></tr><tr><td><code>01:03:13–01:16:12</code></td><td>Abstraction vs. implementation, ISPC gang, <code>foreach</code></td></tr></tbody></table><h2 id="visual-map" tabindex="-1">Visual Map <a class="header-anchor" href="#visual-map" aria-label="Permalink to &quot;Visual Map&quot;">​</a></h2><p>Lecture 3 connects hardware resource limits and programming abstraction in a single flow.</p>',23)),(t(),l(h,null,{default:i(()=>[c(n,{id:"mermaid-347",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20LR%0A%20%20%20%20W%5BParallel%20work%5D%20--%3E%20H%5BHardware%20execution%3Cbr%2F%3Ecores%2C%20SIMD%2C%20threads%5D%0A%20%20%20%20H%20--%3E%20L%5BLatency%20hiding%3Cbr%2F%3Ekeep%20units%20busy%5D%0A%20%20%20%20H%20--%3E%20B%5BBandwidth%20demand%3Cbr%2F%3Ebytes%20per%20second%5D%0A%0A%20%20%20%20B%20--%3E%20X%5BSlowest%20pipeline%20stage%3Cbr%2F%3Elimits%20throughput%5D%0A%20%20%20%20L%20--%3E%20X%0A%0A%20%20%20%20P%5BISPC%20program%3Cbr%2F%3ESPMD%20semantics%5D%20--%3E%20G%5BGang%20of%20instances%3Cbr%2F%3Elogical%20control%20flows%5D%0A%20%20%20%20G%20--%3E%20C%5BCompiler%20mapping%3Cbr%2F%3ESIMD%20instructions%5D%0A%20%20%20%20C%20--%3E%20H%0A%0A%20%20%20%20X%20--%3E%20O%5BOptimization%20target%3Cbr%2F%3Ereuse%20data%2C%20raise%20work%20per%20byte%5D%0A%0A%20%20%20%20classDef%20primary%20fill%3A%23232323%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20secondary%20fill%3A%233b2f20%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20note%20fill%3A%2352676b%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20accent%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20class%20W%2CP%20primary%0A%20%20%20%20class%20H%2CG%2CC%20secondary%0A%20%20%20%20class%20L%20note%0A%20%20%20%20class%20B%2CX%2CO%20accent%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="hardware-parallelism-review" tabindex="-1">Hardware Parallelism Review <a class="header-anchor" href="#hardware-parallelism-review" aria-label="Permalink to &quot;Hardware Parallelism Review&quot;">​</a></h2><p>A modern processor does not use a single parallel mechanism; it combines parallelism at several levels.</p><table tabindex="0"><thead><tr><th>Mechanism</th><th>Unit of parallel work</th><th>Main role</th></tr></thead><tbody><tr><td>Multi-core</td><td>Different instruction streams</td><td>Task/thread parallelism across the whole chip</td></tr><tr><td>Superscalar</td><td>Independent instructions within one stream</td><td>Instruction-level parallelism inside the core</td></tr><tr><td>SIMD</td><td>Multiple data lanes processed by one instruction</td><td>Data-parallel arithmetic throughput</td></tr><tr><td>Hardware multi-threading</td><td>Multiple execution contexts resident on a core</td><td>Reducing idle cycles between stalls</td></tr></tbody></table><p>The conceptual core of the lecture shows a structure that can pick instructions from multiple hardware contexts and issue them simultaneously to scalar and vector execution units, as follows.</p><p><img src="'+p+'" alt="Multi-threaded superscalar core with scalar and vector execution units"></p><p>This figure shows the conceptual implementation of a single core, not the whole multi-core processor. Even with four resident execution contexts, the issue width is at most two instructions, so it does not mean four threads execute simultaneously every clock. Also, this example limits the two simultaneously issued instructions to one scalar and one vector, but the specific combination and selection rules can vary by processor implementation.</p><p>Suppose a hypothetical processor has 16 cores, 4 hardware threads per core, and 8-wide SIMD.</p><ul><li>The number of software thread contexts that can be resident at the same time is <code>16 × 4 = 64</code>.</li><li>Each selected thread can execute an 8-wide vector instruction.</li><li>Filling up to the maximum latency-hiding margin may require <code>16 × 4 × 8 = 512</code> independent data items.</li><li>But the peak arithmetic width of any one cycle and the total amount of resident work are not the same concept. Not all 64 threads execute instructions in the same cycle.</li></ul><p>This distinction matters even more on a GPU. Judging the amount of parallel work needed by only looking at the GPU&#39;s peak ALU count misses the resident warps and the latency-hiding requirements. One reason small DNNs or small tensor operations are inefficient on a large GPU is that there are not enough work items to fill all execution contexts.</p><p><img src="'+u+`" alt="NVIDIA V100 SM with warp contexts and SIMD execution units"></p><p>This figure shows a single SM, not the entire V100 GPU. <code>64 warps × 32 threads = 2,048 threads</code> is the maximum scale of execution contexts that can be resident on the SM for latency hiding, not a statement that 2,048 threads use the ALUs in the same clock. The warp scheduler picks ready warps, and the 16-wide SIMD units in the figure process a 32-thread warp&#39;s instruction over 2 clocks. The actual number of resident warps can be smaller than this maximum depending on the kernel&#39;s register and shared-memory usage.</p><p>A CPU core can also use these four mechanisms together. For example, one core can fetch instructions from two hardware threads and issue multiple independent scalar/vector instructions to several execution units at the same time. Hardware threads become an additional source of independent instructions for the superscalar scheduler.</p><h2 id="hardware-multi-threading-and-latency-hiding" tabindex="-1">Hardware Multi-Threading and Latency Hiding <a class="header-anchor" href="#hardware-multi-threading-and-latency-hiding" aria-label="Permalink to &quot;Hardware Multi-Threading and Latency Hiding&quot;">​</a></h2><p>The basic principle of hardware multi-threading is simple.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>thread 0: compute -&gt; long-latency load -&gt; wait</span></span>
<span class="line"><span>thread 1:                           compute while thread 0 waits</span></span>
<span class="line"><span>thread 2:                                                compute</span></span></code></pre></div><p>Suppose a core repeats a pattern of computing for <code>C</code> cycles and stalling for <code>L</code> cycles. If we simplify by assuming there is no scheduling overhead and the threads execute the same pattern with appropriate staggering, the number of threads needed for full utilization can be reasoned as follows.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>threads needed ≈ ceil((C + L) / C) = 1 + ceil(L / C)</span></span></code></pre></div><p>The lecture&#39;s examples are as follows.</p><table tabindex="0"><thead><tr><th>Compute cycles <code>C</code></th><th>Stall cycles <code>L</code></th><th>One-thread utilization</th><th>Threads for 100% utilization</th></tr></thead><tbody><tr><td>3</td><td>12</td><td><code>3 / 15 = 20%</code></td><td>5</td></tr><tr><td>6</td><td>12</td><td><code>6 / 18 = 33%</code></td><td>3</td></tr></tbody></table><p>Threads beyond the fifth are not always useful. In the first example, the core is already 100% utilized with 5 threads, so scaling up to 8-way multi-threading does not raise peak throughput further.</p><p>Hardware multi-threading has the following costs.</p><ul><li>It needs execution-context storage for each thread&#39;s registers and program counter.</li><li>Because multiple threads share the same execution units, the completion latency of individual threads can grow.</li><li>If register file capacity is fixed, the number of threads and the registers per thread are a trade-off.</li><li>Interference between threads can occur in shared resources such as the cache, branch predictor, and execution queues.</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>When evaluating the number of hardware threads, compare it not against the peak thread count but against &quot;the number of runnable contexts the current workload needs to hide latency.&quot; Threads added after utilization is already saturated can increase resource pressure rather than throughput.</p></div><h2 id="latency-and-bandwidth" tabindex="-1">Latency and Bandwidth <a class="header-anchor" href="#latency-and-bandwidth" aria-label="Permalink to &quot;Latency and Bandwidth&quot;">​</a></h2><p>Latency and bandwidth appear together, but they are not the same metric.</p><table tabindex="0"><thead><tr><th>Term</th><th>Question</th><th>Typical unit</th></tr></thead><tbody><tr><td>Latency</td><td>How long does one request take to complete?</td><td>ns, cycles, seconds</td></tr><tr><td>Bandwidth</td><td>How much data is transferred per unit time?</td><td>bytes/s, items/cycle</td></tr><tr><td>Throughput</td><td>How much work is completed per unit time?</td><td>ops/s, requests/s</td></tr></tbody></table><p>In the highway analogy, if the distance between San Francisco and Stanford is 50 km and cars travel at 100 km/h, the latency of one car is 0.5 hour. If only one car per lane is allowed, throughput is 2 cars/hour.</p><p>There are several ways to raise throughput.</p><ul><li>Raising the speed to 200 km/h reduces latency to 0.25 hour and increases throughput to 4 cars/hour.</li><li>Increasing the number of lanes to four keeps the individual latency at 0.5 hour but increases throughput to 8 cars/hour.</li><li>Piping several cars inside a lane at safe intervals lets you deliver far more cars per unit time without changing the latency.</li></ul><p><img src="`+m+`" alt="Latency and bandwidth"></p><p>The memory system is the same. Prefetching and outstanding requests help hide the effect of long latency and fill the pipeline. But if the pipeline is already full and the transfer width itself is insufficient, even a zero-latency prefetcher would not change the bandwidth ceiling.</p><h2 id="pipelining-and-the-slowest-stage" tabindex="-1">Pipelining and the Slowest Stage <a class="header-anchor" href="#pipelining-and-the-slowest-stage" aria-label="Permalink to &quot;Pipelining and the Slowest Stage&quot;">​</a></h2><p>The laundry example shows how a pipeline&#39;s latency and throughput separate.</p><table tabindex="0"><thead><tr><th>Stage</th><th>Time per load</th></tr></thead><tbody><tr><td>Wash</td><td>45 minutes</td></tr><tr><td>Dry</td><td>60 minutes</td></tr><tr><td>Fold</td><td>15 minutes</td></tr></tbody></table><p>The end-to-end latency of one load is <code>45 + 60 + 15 = 120 minutes</code>. But if you process several loads overlapping, the dryer can dry the previous load while the washer handles the next one, and a person can fold the one before that. Once the pipeline reaches steady state, the overall throughput is limited to 1 load/hour by the slowest dryer.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pipeline throughput = min(each stage throughput)</span></span>
<span class="line"><span>                    = 1 / max(each stage service time)</span></span></code></pre></div><p>If fast upstream stages keep producing more work than a slow downstream stage can absorb, an intermediate queue grows. If the buffer is finite, upstream eventually has to stop as well, and the long-run average throughput converges to the slowest stage&#39;s rate.</p><p>This principle applies directly to a compute pipeline.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>memory system -&gt; cache/load-store unit -&gt; ALU -&gt; result store</span></span>
<span class="line"><span>       the slowest sustained rate determines end-to-end throughput</span></span></code></pre></div><p>An instruction pipeline uses the same idea. In a 4-stage pipeline where fetch, decode, execute, and write-back each take one cycle, the latency of one instruction can be 4 cycles, but once the pipeline is full the throughput can be 1 instruction/cycle. Therefore &quot;it performs one multiply per cycle&quot; usually means the steady-state throughput is 1 operation/cycle, not that the operation latency is 1 cycle.</p><h2 id="memory-bandwidth-bound-execution" tabindex="-1">Memory Bandwidth-Bound Execution <a class="header-anchor" href="#memory-bandwidth-bound-execution" aria-label="Permalink to &quot;Memory Bandwidth-Bound Execution&quot;">​</a></h2><p>The lecture considers the following repeating sequence.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>load 64 bytes -&gt; add -&gt; add -&gt; repeat</span></span></code></pre></div><p>The assumptions are as follows.</p><ul><li>The ALU performs 1 math operation/cycle.</li><li>The load/store unit can issue in parallel with the math unit.</li><li>Memory delivers 8 bytes/cycle.</li><li>Delivering one 64-byte load requires 8 cycles of link occupancy.</li><li>The number of outstanding load requests is limited.</li></ul><p>At first, the processor can issue load requests quickly. But while memory processes one 64-byte request, the processor keeps producing the next request. When the outstanding-request queue fills, the core can no longer issue loads and stalls.</p><p><img src="`+g+`" alt="Timeline of co-issued loads, memory transfers, and processor stalls"></p><p>In the figure, the green blocks are load issues, the gray intervals are part of the latency while the command is being delivered to memory, and the blue blocks are the transfer segments where the 64 bytes of data actually occupy the link. The three outstanding requests overlap the gray intervals to hide latency, but the blue transfers serialize at the bandwidth of 8 bytes/cycle. Therefore, after reaching the request limit, subsequent loads are delayed, and increasing concurrency further does not raise the steady-state bandwidth.</p><p>The important observations in this steady state are as follows.</p><ul><li>The memory link is already 100% busy.</li><li>More hardware threads and outstanding requests can fill the queue further but cannot increase memory&#39;s 8 bytes/cycle.</li><li>The core&#39;s idle regions are determined not by memory latency or queue depth but by the difference between the compute consumption rate and the memory supply rate.</li><li>This is memory bandwidth-bound execution.</li></ul><p>Distinguishing latency-bound from bandwidth-bound changes the remedy.</p><table tabindex="0"><thead><tr><th>Symptom</th><th>Latency-bound response</th><th>Bandwidth-bound response</th></tr></thead><tbody><tr><td>Memory pipeline is empty</td><td>Prefetch, more concurrency, more outstanding requests</td><td>Secondary effect</td></tr><tr><td>Memory link continuously saturated</td><td>Little benefit from adding threads</td><td>Reduce traffic, reuse, compression, higher bandwidth</td></tr><tr><td>Core waiting on memory</td><td>Hide latency with other ready work</td><td>Must reduce the number of bytes per work itself</td></tr></tbody></table><h2 id="arithmetic-intensity-and-data-reuse" tabindex="-1">Arithmetic Intensity and Data Reuse <a class="header-anchor" href="#arithmetic-intensity-and-data-reuse" aria-label="Permalink to &quot;Arithmetic Intensity and Data Reuse&quot;">​</a></h2><p>Element-wise FP32 vector multiplication produces the following traffic.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C[i] = A[i] * B[i]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>read A[i]  = 4 bytes</span></span>
<span class="line"><span>read B[i]  = 4 bytes</span></span>
<span class="line"><span>write C[i] = 4 bytes</span></span>
<span class="line"><span>total      = 12 bytes per multiply</span></span></code></pre></div><p>Using the V100 numbers from the Lecture 3 slides, the calculation is as follows.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>peak FP32 rate ≈ 5,120 ALUs × 1.6 GHz</span></span>
<span class="line"><span>               ≈ 8.2 trillion multiplies/s</span></span>
<span class="line"><span></span></span>
<span class="line"><span>required bandwidth ≈ 8.2 × 10^12 × 12 bytes</span></span>
<span class="line"><span>                   ≈ 98 TB/s</span></span>
<span class="line"><span></span></span>
<span class="line"><span>available HBM2 bandwidth ≈ 0.9 TB/s</span></span></code></pre></div><p>Therefore, looking only at the compute-to-bandwidth ratio, the expected ALU utilization is roughly <code>0.9 / 98</code>, i.e. below 1%. In a real execution, instruction overhead, cache behavior, and write policies also play a role, but the order of magnitude of the bottleneck is already revealed by this calculation.</p><p>This example shows that &quot;there is a lot of parallelism&quot; and &quot;the machine is used efficiently&quot; are different things. Even if every element is independent and SIMD-friendly, if data cannot be supplied fast enough, the ALUs spend most of their time waiting.</p><p>To improve performance, you must reduce off-chip memory accesses per work.</p><ul><li>Reuse data that the same thread has already read: temporal locality</li><li>Cooperatively reuse data read by multiple threads from cache/shared memory</li><li>Perform additional operations in registers instead of writing an intermediate value to memory and reading it back</li><li>With kernel fusion, the consumer uses the producer&#39;s result directly without materializing it in off-chip memory</li><li>Keep a small working set in on-chip memory with tiling</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>A cache only reduces traffic when reuse exists. In a vector multiply that streams millions of elements exactly once each, even using every cache line fully does not make the compulsory traffic disappear. Prefetching also only hides latency; it does not increase the bandwidth of an already saturated memory link.</p></div><h2 id="abstraction-vs-implementation" tabindex="-1">Abstraction vs. Implementation <a class="header-anchor" href="#abstraction-vs-implementation" aria-label="Permalink to &quot;Abstraction vs. Implementation&quot;">​</a></h2><p>The central question of the second half of the lecture is to distinguish &quot;what does the program compute?&quot; from &quot;how does the parallel machine perform that computation?&quot;.</p><table tabindex="0"><thead><tr><th>View</th><th>Main question</th></tr></thead><tbody><tr><td>Semantics</td><td>What result does this operation and program mean?</td></tr><tr><td>Implementation</td><td>Which thread/core/lane performs which operation, and when?</td></tr><tr><td>Scheduling</td><td>Among several valid execution orders, which mapping is chosen?</td></tr></tbody></table><p>One semantics can have many valid implementations. For example, even if program instance 0 executes all independent loop iterations sequentially, the result can be correct, and dividing them among several instances in interleaved, blocked, or dynamic ways can give the same result.</p><p>When reading a parallel program, trace it in two steps.</p><ol><li>Using only the rules of the abstraction, confirm what result should come out.</li><li>Assuming the target implementation, track which core, thread, and SIMD lane does which work at which point in time.</li></ol><p>Mixing the two steps commonly leads to the following confusions.</p><ul><li>Assuming a logical program instance is identical to an OS thread.</li><li>Thinking that because scalar operations appear in SPMD source code, only scalar instructions are executed.</li><li>Assuming the execution order of <code>foreach</code> iterations follows source order.</li><li>Judging correct semantics and fast implementation by the same criterion.</li></ul><h2 id="ispc-and-the-spmd-programming-model" tabindex="-1">ISPC and the SPMD Programming Model <a class="header-anchor" href="#ispc-and-the-spmd-programming-model" aria-label="Permalink to &quot;ISPC and the SPMD Programming Model&quot;">​</a></h2><p>ISPC stands for Intel SPMD Program Compiler. It uses a source syntax similar to C, but its core programming model is SPMD (single program, multiple data).</p><p>In SPMD, you define one function body, and multiple logical instances execute that body on different data.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>one ISPC function</span></span>
<span class="line"><span>    -&gt; program instance 0 handles some data</span></span>
<span class="line"><span>    -&gt; program instance 1 handles some data</span></span>
<span class="line"><span>    -&gt; ...</span></span>
<span class="line"><span>    -&gt; program instance W-1 handles some data</span></span></code></pre></div><p>When an ordinary C++ caller invokes an exported ISPC function, the following logically happens.</p><ol><li>A gang of <code>programCount</code> program instances begins.</li><li>All instances execute the same ISPC function body.</li><li>Each instance can have its own <code>programIndex</code> and private local state.</li><li>After all instances finish, the ISPC function returns.</li><li>The C++ caller&#39;s single control flow resumes.</li></ol><p>A program instance is a logical execution entity of the abstraction. The reason it is not called an OS thread or hardware thread is to avoid fixing the implementation in advance. Looking only at the result semantics, you can also imagine executing instances one by one sequentially or with several OS threads. The actual target implementation of ISPC is to execute one gang with SIMD instructions.</p><h2 id="ispc-gang-and-program-instances" tabindex="-1">ISPC Gang and Program Instances <a class="header-anchor" href="#ispc-gang-and-program-instances" aria-label="Permalink to &quot;ISPC Gang and Program Instances&quot;">​</a></h2><p>A gang is the set of logical program instances that execute one ISPC function together. Each instance can choose a different control-flow path depending on varying conditions. The compiler implements this semantics with SIMD lane masks and convergence.</p><table tabindex="0"><thead><tr><th>ISPC concept</th><th>Meaning</th></tr></thead><tbody><tr><td>Gang</td><td>The set of instances executed together in one ISPC function invocation</td></tr><tr><td>Program instance</td><td>A logical control flow executing the SPMD function</td></tr><tr><td><code>programCount</code></td><td>The number of instances in the gang</td></tr><tr><td><code>programIndex</code></td><td>The current instance&#39;s ID, <code>0 ... programCount-1</code></td></tr></tbody></table><p>If the gang size is 8, each instance executes the same code while observing a different <code>programIndex</code>. You can use this to divide up array work directly.</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Simplified ISPC form to illustrate the concept</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (uniform </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> base </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; base </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> N; base </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> programCount) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> base </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> programIndex;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    output</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[i] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> transform</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">input</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[i]);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Instance 0 handles <code>0, 8, 16, ...</code>, and instance 1 handles <code>1, 9, 17, ...</code>. Combining the results of all instances processes the entire array.</p><p>What matters here is the number of copies of local variables. Values that differ per instance, such as <code>i</code> and <code>input[i]</code>, exist per logical instance. On the other hand, arguments and loop bounds shared by all instances can be represented as a single value.</p><h2 id="uniform-and-varying-values" tabindex="-1">Uniform and Varying Values <a class="header-anchor" href="#uniform-and-varying-values" aria-label="Permalink to &quot;Uniform and Varying Values&quot;">​</a></h2><p>The ISPC type system expresses whether a value is the same across the whole gang or different per instance.</p><table tabindex="0"><thead><tr><th>Kind</th><th>Meaning</th><th>Example</th></tr></thead><tbody><tr><td><code>uniform</code></td><td>One value identical for all instances</td><td><code>N</code>, pointer base, loop bound</td></tr><tr><td><code>varying</code></td><td>A value that differs per instance</td><td><code>programIndex</code>, per-element input, lane-local accumulator</td></tr></tbody></table><p>A scalar value without an explicit modifier is generally interpreted as varying. <code>programCount</code> is uniform and <code>programIndex</code> is varying.</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">uniform </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> width </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> programCount;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lane </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> programIndex;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> index </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> blockStart </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lane;</span></span></code></pre></div><p><code>uniform</code> matters for compiler optimization beyond simple documentation. When the compiler knows a value is the same in all lanes, it can choose a cheaper implementation such as a scalar register, a scalar branch, or a broadcast. But a programmer cannot mistakenly make a value that is actually varying into a uniform one. If you try to assign different lane values into a uniform destination, the meaning becomes ambiguous and a compile-time type error can occur.</p><p>The boundary between uniform and varying is also where the SIMD implementation below the abstraction becomes visible. To understand ISPC semantics, you must always check &quot;is this variable one per gang, or one per instance?&quot;.</p><h2 id="interleaved-and-blocked-assignment" tabindex="-1">Interleaved and Blocked Assignment <a class="header-anchor" href="#interleaved-and-blocked-assignment" aria-label="Permalink to &quot;Interleaved and Blocked Assignment&quot;">​</a></h2><p>Even the same array operation can assign work to instances differently.</p><table tabindex="0"><thead><tr><th>Assignment</th><th>Instance 0 example</th><th>Instance 1 example</th></tr></thead><tbody><tr><td>Interleaved</td><td><code>0, 8, 16, 24, ...</code></td><td><code>1, 9, 17, 25, ...</code></td></tr><tr><td>Blocked</td><td><code>0, 1, 2, 3, ...</code></td><td>The next contiguous block</td></tr></tbody></table><p>Looking only at the logical work distribution, both schemes can be correct because each element is processed exactly once. But in a SIMD implementation, performance differs greatly depending on which addresses the instances access at any one moment.</p><p><img src="`+y+`" alt="ISPC iteration assignment"></p><p>With interleaved assignment, the lanes of the same loop step access contiguous addresses.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>step 0: lane addresses = 0, 1, 2, 3, 4, 5, 6, 7</span></span>
<span class="line"><span>step 1: lane addresses = 8, 9, 10, 11, 12, 13, 14, 15</span></span></code></pre></div><p>This pattern is easy to implement with a single packed vector load. In contrast, blocked assignment gives each instance a contiguous block, but at the same SIMD instruction moment the lanes access far-apart addresses.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>step 0: lane addresses = 0, 8, 16, 24, 32, 40, 48, 56</span></span></code></pre></div><p>This pattern may require a gather instruction. Therefore, the statement &quot;each thread has contiguous data&quot; is not enough to judge SIMD memory efficiency. You must look at the addresses that the lanes of the actual vector instruction access at the same moment.</p><h2 id="the-foreach-abstraction" tabindex="-1">The <code>foreach</code> Abstraction <a class="header-anchor" href="#the-foreach-abstraction" aria-label="Permalink to &quot;The \`foreach\` Abstraction&quot;">​</a></h2><p><code>foreach</code> is ISPC&#39;s core construct for declaring a parallel iteration set.</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">foreach</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ... N) {</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    output</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[i] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> transform</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">input</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[i]);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The semantics of this code are as follows.</p><ul><li>The whole gang performs the iterations <code>0 ... N-1</code>.</li><li>Each iteration must be able to execute independently of the others.</li><li>The implementation decides which program instance handles which iteration.</li><li>The programmer focuses on the meaning of the iterations instead of doing manual per-instance assignment.</li></ul><p>Valid implementations that the compiler/runtime can choose include the following.</p><ol><li>One instance executes all iterations.</li><li>Iterations are assigned to instances in an interleaved fashion.</li><li>They are divided into contiguous blocks.</li><li>A shared counter is used for dynamic assignment.</li></ol><p>Of course, the real ISPC compiler chooses a mapping suited to SIMD. The important point is that <code>foreach</code> semantics does not promise any single specific mapping.</p><p>This abstraction hides low-level scheduling details and states the programmer intent &quot;for each element, perform this operation independently.&quot; The compiler can use this information to vectorize more reliably.</p><h2 id="parallel-loop-correctness" tabindex="-1">Parallel Loop Correctness <a class="header-anchor" href="#parallel-loop-correctness" aria-label="Permalink to &quot;Parallel Loop Correctness&quot;">​</a></h2><p>Because <code>foreach</code> iterations execute potentially in parallel, merely reading the source code like a sequential loop does not guarantee correctness. You must check whether the memory effects of each iteration are independent of each other.</p><p>A safe example is an iteration <code>i</code> that reads only <code>input[i]</code> and writes only <code>output[2*i]</code> and <code>output[2*i+1]</code>. Its output range does not overlap with other iterations&#39; output ranges.</p><p>On the other hand, the following pattern is dangerous.</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">foreach</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ... N) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &amp;&amp;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> input</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[i] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">        output</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> input</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[i];</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    else</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">        output</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[i] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> input</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[i];</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Iterations <code>i</code> and <code>i-1</code> can both write to the same <code>output[i-1]</code>. Since it is not determined which write arrives last, the output is undefined.</p><p>When reviewing a parallel loop, check the following.</p><ul><li>Do different iterations write to the same location?</li><li>Does one iteration read a value written by another iteration without synchronization?</li><li>Is an update a read-modify-write without atomic or reduction semantics?</li><li>Does correctness happen to depend only on a particular <code>programCount</code> or the current mapping?</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>The claim &quot;the current compiler assigns interleaved, so there is no collision&quot; cannot serve as grounds for <code>foreach</code> correctness. The result must be the same under other valid schedules that the abstraction allows.</p></div><h2 id="reduction-and-cross-instance-operations" tabindex="-1">Reduction and Cross-Instance Operations <a class="header-anchor" href="#reduction-and-cross-instance-operations" aria-label="Permalink to &quot;Reduction and Cross-Instance Operations&quot;">​</a></h2><p>Operations that combine the values of many iterations into one, such as the sum of an entire array, are different from a simple independent map.</p><p>You cannot directly add each lane&#39;s varying value into a uniform accumulator that exists only once for the whole gang. Since there is no way to implicitly convert multiple lane values into a single uniform value, the ISPC compiler rejects it with a compile-time type error. Conversely, if you make only per-instance varying accumulators, the partial sums are multiple, so you cannot immediately return them as the single uniform scalar return value the C++ caller expects.</p><p>A correct reduction consists of two steps.</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> partial </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">foreach</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ... N)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    partial </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+=</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> input</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[i];</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">uniform </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> total </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> reduce_add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(partial);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> total;</span></span></code></pre></div><ol><li>Each instance accumulates its elements into a private varying accumulator.</li><li><code>reduce_add</code> combines the gang&#39;s partial values into a single uniform result.</li></ol><p>ISPC provides several primitives for communication between instances.</p><table tabindex="0"><thead><tr><th>Operation</th><th>Meaning</th></tr></thead><tbody><tr><td><code>reduce_add(x)</code></td><td>Returns the sum of <code>x</code> over currently active instances as a uniform value</td></tr><tr><td><code>reduce_min(x)</code></td><td>Returns the minimum over currently active instances as a uniform value</td></tr><tr><td><code>broadcast(x, k)</code></td><td>Delivers the value of instance <code>k</code> to all instances</td></tr><tr><td><code>rotate(x, offset)</code></td><td>Moves instance values circularly within the gang</td></tr></tbody></table><p>These operations can be implemented with instruction sequences such as SIMD horizontal reduction, shuffle, and permute. The programmer uses the cross-instance semantics, and the compiler chooses the implementation that fits the target ISA.</p><h2 id="spmd-abstraction-and-simd-implementation" tabindex="-1">SPMD Abstraction and SIMD Implementation <a class="header-anchor" href="#spmd-abstraction-and-simd-implementation" aria-label="Permalink to &quot;SPMD Abstraction and SIMD Implementation&quot;">​</a></h2><p>The most important distinction in ISPC can be summarized in one sentence.</p><blockquote><p>The programmer writes SPMD, and the compiler generates SIMD.</p></blockquote><table tabindex="0"><thead><tr><th>Layer</th><th>ISPC view</th></tr></thead><tbody><tr><td>Source abstraction</td><td><code>programCount</code> logical instances execute the same program</td></tr><tr><td>Per-instance state</td><td><code>programIndex</code>, varying local variables</td></tr><tr><td>Compiler mapping</td><td>Maps instances to vector lanes</td></tr><tr><td>Generated code</td><td>Vector instructions such as AVX2, AVX-512, ARM Neon</td></tr><tr><td>Control flow</td><td>Implements varying branches using lane masks</td></tr></tbody></table><p>The gang size is usually tied to the hardware SIMD width or a small multiple of it. The compiler generates the exported ISPC function as an object file that can be linked from C/C++. The C++ caller invokes it like an ordinary function, but the function body contains vector instructions.</p><p>With a varying condition, each logical instance can choose a different branch. On SIMD hardware, when one path executes, only the lanes that chose that path are enabled, and the mask is switched for the other path. Therefore the semantics are preserved, but divergent control flow lowers lane utilization.</p><p>This model also connects to GPUs. An NVIDIA GPU programmer writes a scalar thread program, but the hardware groups threads that share the same program counter into a warp and executes them similarly to SIMD. ISPC provides a similar SPMD-on-SIMD abstraction at the compiler level, targeting the CPU vector ISA.</p><h2 id="ispc-tasks-and-multi-core-execution" tabindex="-1">ISPC Tasks and Multi-Core Execution <a class="header-anchor" href="#ispc-tasks-and-multi-core-execution" aria-label="Permalink to &quot;ISPC Tasks and Multi-Core Execution&quot;">​</a></h2><p>The gang described so far is a way in which one CPU thread executes SIMD instructions on one core. Therefore, using only gangs utilizes SIMD lanes but does not automatically utilize multiple CPU cores.</p><p>ISPC provides a separate task abstraction to express multi-core execution.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C++ caller</span></span>
<span class="line"><span>  -&gt; launch multiple ISPC tasks</span></span>
<span class="line"><span>      -&gt; task scheduler / worker pool</span></span>
<span class="line"><span>          -&gt; an available worker executes one gang</span></span>
<span class="line"><span>          -&gt; other workers execute additional gangs</span></span></code></pre></div><p>Tasks and gangs are different parallelism levels.</p><table tabindex="0"><thead><tr><th>Level</th><th>Purpose</th><th>Hardware mapping</th></tr></thead><tbody><tr><td>Task parallelism</td><td>Execute several work chunks independently</td><td>CPU cores / software worker threads</td></tr><tr><td>Gang parallelism</td><td>Data-parallel work within one chunk</td><td>SIMD lanes within one core</td></tr></tbody></table><p>Tasks are enqueued asynchronously and may execute immediately or on another processor. No fixed one-to-one mapping between task index and physical core is guaranteed, nor is the order of task execution. Actual placement and load balancing are decided by the connected task system.</p><p>To get full CPU utilization on a workload like Assignment 1, you need a hierarchical decomposition: divide the large input into tasks to feed multiple cores, and within each task let an ISPC gang use SIMD.</p><h2 id="the-abstraction-ladder" tabindex="-1">The Abstraction Ladder <a class="header-anchor" href="#the-abstraction-ladder" aria-label="Permalink to &quot;The Abstraction Ladder&quot;">​</a></h2><p>ISPC is a relatively low-level language. It exposes <code>programIndex</code>, <code>programCount</code>, uniform/varying, and cross-instance operations, so the programmer can create precise cooperation and memory mappings. At the same time, if misused, it can also write programs that are correct only for a certain gang size, or programs with data races.</p><p>Higher abstractions remove some low-level control.</p><table tabindex="0"><thead><tr><th>Abstraction level</th><th>Programmer expresses</th><th>System decides</th></tr></thead><tbody><tr><td>Manual ISPC indexing</td><td>Exact work and address per instance</td><td>SIMD instruction selection</td></tr><tr><td>ISPC <code>foreach</code></td><td>Independent iteration set</td><td>Instance assignment and vector mapping</td></tr><tr><td>Collection <code>map</code></td><td>Element-wise function</td><td>Loop, indexing, partition, scheduling</td></tr><tr><td>NumPy/PyTorch tensor op</td><td>Whole-array/tensor transformation</td><td>Kernel selection, fusion, device mapping</td></tr></tbody></table><p>Low-level control gives optimization opportunities but also increases the burden of correctness and portability. High-level abstractions give the compiler/runtime more scheduling freedom, but it can be hard to observe whether the desired memory mapping or fusion was actually chosen.</p><p>From the perspective of Lecture 3, a programming model is a framework for thinking about the organization of a parallel program, and one abstraction allows several valid implementations. When reading later lectures as well, you should ask separately, &quot;What semantics does this API guarantee, and how does the current system map them?&quot;.</p><h2 id="gpu-systems-lens" tabindex="-1">GPU Systems Lens <a class="header-anchor" href="#gpu-systems-lens" aria-label="Permalink to &quot;GPU Systems Lens&quot;">​</a></h2><p>The concepts of Lecture 3 apply directly to interpreting GPUs and AI workloads.</p><p>The GPU/LLM interpretation in this section and the Practical Tips that follow are additional notes applying the lecture&#39;s concepts to the systems viewpoint of this repository. They should not be taken as direct claims of the lecture video or slides.</p><table tabindex="0"><thead><tr><th>Lecture 3 concept</th><th>GPU/AI systems interpretation</th></tr></thead><tbody><tr><td>Latency hiding</td><td>Issue another ready warp while one warp waits for memory</td></tr><tr><td>Bandwidth ceiling</td><td>The bytes/s HBM can supply limits kernel throughput</td></tr><tr><td>Pipeline bottleneck</td><td>The slowest stage among HBM, interconnect, Tensor Cores, and collectives determines the overall rate</td></tr><tr><td>Arithmetic intensity</td><td>If FLOPs per byte is below the machine balance, it is memory-bound</td></tr><tr><td>ISPC gang</td><td>A logical SPMD group similar to a CUDA warp</td></tr><tr><td>Varying control flow</td><td>Warp divergence and lane masking</td></tr><tr><td><code>foreach</code></td><td>Independent thread/iteration semantics of an element-wise kernel</td></tr><tr><td>Cross-instance operation</td><td>Warp shuffle, vote, reduction</td></tr><tr><td>ISPC task</td><td>A larger work decomposition level like a CUDA block or CPU worker task</td></tr><tr><td>SPMD vs. SIMD</td><td>The distinction between the CUDA thread abstraction and the warp/SIMT hardware implementation</td></tr></tbody></table><p>Applied to LLM training and inference, the following questions matter.</p><ul><li>Does the kernel&#39;s FLOPs/byte match the compute-to-HBM balance of the target GPU?</li><li>Do KV cache reads, activation materialization, and optimizer state traffic saturate HBM bandwidth?</li><li>Can kernel fusion or tiling reduce intermediate traffic?</li><li>In tensor-parallel collectives, is network bandwidth playing the role of the compute pipeline&#39;s dryer?</li><li>Do more warps hide memory latency, or do they only compete over already saturated bandwidth?</li><li>Are you confusing logical thread semantics with the warp-level implementation and missing races or divergence?</li></ul><h2 id="practical-tips-and-notes" tabindex="-1">Practical Tips and Notes <a class="header-anchor" href="#practical-tips-and-notes" aria-label="Permalink to &quot;Practical Tips and Notes&quot;">​</a></h2><h3 id="distinguish-latency-bound-from-bandwidth-bound-first" tabindex="-1">Distinguish latency-bound from bandwidth-bound first <a class="header-anchor" href="#distinguish-latency-bound-from-bandwidth-bound-first" aria-label="Permalink to &quot;Distinguish latency-bound from bandwidth-bound first&quot;">​</a></h3><p>Both states can look like &quot;the core waits for memory&quot; in a profiler. But the prescription differs.</p><table tabindex="0"><thead><tr><th>Observation</th><th>Likely issue</th><th>First check</th></tr></thead><tbody><tr><td>Low memory throughput, many dependency stalls</td><td>Latency/insufficient concurrency</td><td>Occupancy, outstanding requests, dependency chains</td></tr><tr><td>HBM throughput near sustained peak</td><td>Bandwidth saturation</td><td>Bytes per output, reuse, fusion, data type</td></tr><tr><td>Slow only on small inputs</td><td>Insufficient parallel work or launch overhead</td><td>Active blocks, number of waves, kernel duration</td></tr><tr><td>Throughput unchanged even when raising occupancy</td><td>Bandwidth or compute pipeline saturation</td><td>Roofline position, achieved bandwidth/FLOPs</td></tr></tbody></table><h3 id="use-sustained-bandwidth-not-peak-bandwidth" tabindex="-1">Use sustained bandwidth, not peak bandwidth <a class="header-anchor" href="#use-sustained-bandwidth-not-peak-bandwidth" aria-label="Permalink to &quot;Use sustained bandwidth, not peak bandwidth&quot;">​</a></h3><p>Datasheet bandwidth is the interface&#39;s theoretical peak. The sustained bandwidth a real kernel achieves is lower depending on access pattern, transaction granularity, ECC, contention, and read/write mix. For roofline-style computations, it is safer to use a copy or streaming benchmark measured on the same workload class as the baseline.</p><h3 id="do-the-byte-accounting-first" tabindex="-1">Do the byte accounting first <a class="header-anchor" href="#do-the-byte-accounting-first" aria-label="Permalink to &quot;Do the byte accounting first&quot;">​</a></h3><p>Before kernel optimization, write down the following per output element.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mandatory reads + mandatory writes + temporary traffic + metadata/index traffic</span></span></code></pre></div><p>Then compute the effective bandwidth from the measured runtime and data volume.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>effective bandwidth = bytes transferred / execution time</span></span></code></pre></div><p>If the value is close to the hardware&#39;s sustained limit, reducing traffic takes priority over adding threads or instruction-level tuning.</p><h3 id="treat-foreach-independence-as-a-proof-obligation" tabindex="-1">Treat <code>foreach</code> independence as a proof obligation <a class="header-anchor" href="#treat-foreach-independence-as-a-proof-obligation" aria-label="Permalink to &quot;Treat \`foreach\` independence as a proof obligation&quot;">​</a></h3><p>Do not think of <code>foreach</code> as a fast version of an ordinary <code>for</code>. Review whether the result is identical for every iteration order and parallel interleaving. If write sets overlap, change the partition or use explicit parallel primitives such as atomics, reductions, or prefix sums.</p><h3 id="look-at-data-assignment-from-the-lane-time-perspective" tabindex="-1">Look at data assignment from the lane-time perspective <a class="header-anchor" href="#look-at-data-assignment-from-the-lane-time-perspective" aria-label="Permalink to &quot;Look at data assignment from the lane-time perspective&quot;">​</a></h3><p>Even if a blocked partition looks good in terms of locality from the software thread&#39;s viewpoint, if the addresses that SIMD lanes access simultaneously form a stride pattern, gathers can occur. Check both of the following questions.</p><ul><li>Which addresses does one instance visit over time?</li><li>Which set of addresses do all lanes visit in the same instruction?</li></ul><h3 id="uniform-annotation-is-a-measurable-optimization-hint" tabindex="-1">Uniform annotation is a measurable optimization hint <a class="header-anchor" href="#uniform-annotation-is-a-measurable-optimization-hint" aria-label="Permalink to &quot;Uniform annotation is a measurable optimization hint&quot;">​</a></h3><p>Representing a value that is the same across the whole gang as uniform can reduce vector registers and mask operations. However, do not add annotations indiscriminately; confirm the actual effect through the generated assembly, ISPC&#39;s performance warnings, or benchmarks.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>When debugging ISPC code, spread a small <code>programCount</code> and small array on paper and make a table of per-instance <code>programIndex</code>, local values, and read/write addresses. Only when this trace is correct can you analyze the SIMD assembly and performance.</p></div><h3 id="quick-reference" tabindex="-1">Quick Reference <a class="header-anchor" href="#quick-reference" aria-label="Permalink to &quot;Quick Reference&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Symptom</th><th>First check</th></tr></thead><tbody><tr><td>Many threads but low ALU utilization</td><td>HBM bandwidth and bytes/op</td></tr><tr><td>Not faster even when adding threads</td><td>Whether latency is already hidden or another stage is saturated</td></tr><tr><td>ISPC blocked version is slow</td><td>SIMD gather and per-lane address stride</td></tr><tr><td><code>foreach</code> result differs between runs</td><td>Overlapping writes or read-after-write between iterations</td></tr><tr><td>Uniform/varying type error occurs</td><td>Whether a per-gang single value and per-instance multiple values are mixed</td></tr><tr><td>ISPC uses only one core</td><td>Whether only gangs are used and task parallelism is not launched</td></tr><tr><td>Cannot return the reduction result</td><td>Whether <code>reduce_add</code> is needed after per-instance partials</td></tr></tbody></table><h2 id="lecture-summary" tabindex="-1">Lecture Summary <a class="header-anchor" href="#lecture-summary" aria-label="Permalink to &quot;Lecture Summary&quot;">​</a></h2><p>This lecture showed that a parallel processor&#39;s performance cannot be explained by latency hiding alone. Hardware multi-threading raises execution unit utilization by running other work during stalls, but it does not increase peak throughput or memory bandwidth. In a steady state with a full pipeline, the overall throughput is limited by the rate of the slowest stage.</p><p>Element-wise vector multiplication can be memory-bound even with sufficient independent work and SIMD coherence. The gap between the roughly 98 TB/s the compute pipeline demands on a V100 and the actual 900 GB/s HBM2 bandwidth shows that the key to performance is not simply creating more parallel work but reducing memory traffic per work and raising data reuse.</p><p>ISPC is a concrete example for understanding parallel programming abstractions. The programmer uses SPMD semantics in which many program instances execute the same function on different data, and the compiler implements it with SIMD instructions. <code>foreach</code> declares an independent iteration set and leaves scheduling to the system. For correctness, the result must be the same without races under every valid mapping, and operations that require communication between instances, like reductions, must use dedicated primitives.</p><p>The three sentences to remember in the end are as follows.</p><ul><li>Hiding latency and solving the bandwidth limit are different things.</li><li>Pipeline throughput is determined by the slowest sustained stage.</li><li>You must distinguish what a parallel abstraction means from how the hardware implements it.</li></ul><h2 id="key-terms" tabindex="-1">Key Terms <a class="header-anchor" href="#key-terms" aria-label="Permalink to &quot;Key Terms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td>Latency</td><td>The time from the start to completion of one operation or request</td></tr><tr><td>Bandwidth</td><td>The amount of data a system can transfer per unit time</td></tr><tr><td>Throughput</td><td>The amount of work completed per unit time</td></tr><tr><td>Pipelining</td><td>A method of executing different stages of multiple work items overlapping</td></tr><tr><td>Bottleneck</td><td>The slowest stage that limits the pipeline&#39;s overall sustained throughput</td></tr><tr><td>Memory bandwidth-bound</td><td>A state in which the compute rate is limited by the memory&#39;s data supply rate</td></tr><tr><td>Arithmetic intensity</td><td>The number of arithmetic operations performed per byte of memory traffic</td></tr><tr><td>SPMD</td><td>A model in which multiple logical instances execute one program on different data</td></tr><tr><td>SIMD</td><td>An implementation that applies one instruction to multiple data lanes simultaneously</td></tr><tr><td>Gang</td><td>A set of ISPC program instances executed together</td></tr><tr><td>Program instance</td><td>A logical entity executing an ISPC SPMD function</td></tr><tr><td><code>programCount</code></td><td>The number of program instances in the gang</td></tr><tr><td><code>programIndex</code></td><td>The ID of the current program instance</td></tr><tr><td><code>uniform</code></td><td>The identical value shared by all instances of the gang</td></tr><tr><td>Varying</td><td>A value that differs per program instance</td></tr><tr><td><code>foreach</code></td><td>An ISPC construct that declares an independent iteration set for the whole gang to perform</td></tr><tr><td>Gather</td><td>A vector load that collects data from non-contiguous addresses of several SIMD lanes</td></tr><tr><td>Reduction</td><td>An operation that combines values from multiple instances into a single result</td></tr><tr><td>Cross-instance operation</td><td>An operation that combines or moves values between instances within a gang</td></tr><tr><td>ISPC task</td><td>A coarse-grained parallel work unit for utilizing multiple CPU cores</td></tr></tbody></table><h2 id="questions" tabindex="-1">Questions <a class="header-anchor" href="#questions" aria-label="Permalink to &quot;Questions&quot;">​</a></h2><ol><li>What do latency and bandwidth each measure?</li><li>Why does hardware multi-threading not increase memory bandwidth?</li><li>How many threads does a workload that computes for 3 cycles then stalls for 12 cycles need for full utilization?</li><li>What costs can occur when hardware threads are increased beyond the needed number?</li><li>What determines a pipeline&#39;s steady-state throughput?</li><li>Why can a 4-stage instruction pipeline have 1 instruction/cycle throughput while instruction latency is 4 cycles?</li><li>Why does element-wise FP32 multiplication on a V100 stay below 1% compute efficiency even though it is SIMD-friendly?</li><li>Why can caches and prefetching not eliminate the bandwidth bottleneck in a streaming workload?</li><li>How do the semantics and implementation of a programming abstraction differ?</li><li>In ISPC&#39;s SPMD model, what are a gang and a program instance?</li><li>Are <code>programCount</code> and <code>programIndex</code> uniform or varying, respectively?</li><li>Why can interleaved assignment be better than blocked assignment for a packed vector load?</li><li>What does ISPC <code>foreach</code> guarantee, and what does it not guarantee?</li><li>If different <code>foreach</code> iterations can write to the same output location, why does it become an undefined result?</li><li>In an array sum, why are both a varying partial accumulator and <code>reduce_add</code> needed?</li><li>What does it mean that &quot;the ISPC programmer writes SPMD and the compiler generates SIMD&quot;?</li><li>Why can an ISPC gang alone not use all CPU cores?</li><li>What metrics can you check first to distinguish latency-bound from bandwidth-bound in an LLM kernel?</li></ol><h2 id="answers" tabindex="-1">Answers <a class="header-anchor" href="#answers" aria-label="Permalink to &quot;Answers&quot;">​</a></h2><ol><li>Latency is the completion time of one request, and bandwidth is the amount of data that can be transferred per unit time.</li><li>Hardware multi-threading only executes other work until memory responds; it does not widen the bytes/cycle the memory interface itself delivers.</li><li><code>ceil((3 + 12) / 3) = 5</code> threads.</li><li>Increased execution-context storage, fewer registers per thread, increased latency of individual threads, and interference in caches and execution resources can occur.</li><li>The stage with the lowest sustained throughput, i.e. the bottleneck, determines it.</li><li>Because different instructions can be simultaneously in different stages of the pipeline, once the pipeline is full, one completes every cycle.</li><li>One multiply reads two FP32 inputs and writes one output, requiring 12 bytes, and the roughly 98 TB/s required by the ALU peak rate is far larger than the 900 GB/s HBM2 bandwidth.</li><li>Caches cannot remove compulsory traffic that has no reuse, and prefetching only starts transfers earlier; it cannot raise the bytes/s of an already saturated link.</li><li>Semantics define what result the program should compute, and implementation decides how to place those operations across cores, threads, lanes, and time.</li><li>A gang is the set of logical instances executed together in one invocation, and a program instance is a logical entity that executes the same SPMD function with its own data and state.</li><li><code>programCount</code> is uniform and <code>programIndex</code> is varying.</li><li>Because the SIMD lanes at the same moment access contiguous addresses, it is easy to implement with a single packed load. In blocked assignment the addresses between lanes are far apart, so a gather may be needed.</li><li>It guarantees the semantics that the whole gang performs the iteration set, but it does not guarantee the mapping of which instance handles which iteration or the execution order.</li><li>Because the write order changes with the parallel schedule, and it is not defined which value remains last.</li><li>The varying partial enables per-instance local accumulation, and <code>reduce_add</code> combines the multiple partials into a single uniform scalar the caller can receive.</li><li>In the source you reason with the semantics of several logical control flows, but in the generated binary those instances are mapped to vector lanes and execute one vector instruction together.</li><li>Because one gang is executed as SIMD by one CPU thread on one core. Using multiple cores requires separate ISPC tasks or software task parallelism.</li><li>Look at achieved HBM bandwidth, memory-pipeline utilization, occupancy, outstanding requests, and FLOPs/byte together. If bandwidth is close to the sustained peak, reducing traffic takes priority over concurrency.</li></ol>`,190))])}const A=s(b,[["render",f]]);export{P as __pageData,A as default};
